// Package store defines the persistence contract for the control service.
//
// The P1 implementation is a plain-file store, but every method here is
// deliberately shaped so a SQL backend can implement it without changing
// callers. Two rules keep that true:
//
//   - IDs are generated by the application, never by the backend.
//   - Multi-object writes go through Tx, never through back-to-back calls.
package store

import (
	"context"
	"errors"
	"time"
)

var ErrNotFound = errors.New("not found")

type ID string

type SubjectKind string

const (
	KindUser      SubjectKind = "user"
	KindAnonymous SubjectKind = "anonymous"
	KindSystem    SubjectKind = "system"
)

type Subject struct {
	Kind  SubjectKind `json:"kind"`
	ID    ID          `json:"id,omitempty"`
	Phone string      `json:"phone,omitempty"` // masked, display only
}

func Anonymous() Subject { return Subject{Kind: KindAnonymous} }

func UserSubject(u *User) Subject {
	return Subject{Kind: KindUser, ID: u.ID, Phone: MaskPhone(u.Phone)}
}

type User struct {
	ID         ID         `json:"id"`
	Phone      string     `json:"phone"`
	Name       string     `json:"name"`
	Role       string     `json:"role"`
	CreatedAt  time.Time  `json:"created_at"`
	DisabledAt *time.Time `json:"disabled_at,omitempty"`
}

func (u *User) Disabled() bool { return u.DisabledAt != nil }

type Policy struct {
	ID          ID          `json:"id"`
	SubjectKind SubjectKind `json:"subject_kind"`
	SubjectID   ID          `json:"subject_id"`
	Resource    string      `json:"resource"`
	Action      string      `json:"action"`
	Effect      string      `json:"effect"`
	GrantedBy   ID          `json:"granted_by,omitempty"`
	GrantedAt   time.Time   `json:"granted_at"`
}

type Device struct {
	Key      string         `json:"key"`
	Name     string         `json:"name"`
	Room     string         `json:"room,omitempty"`
	Provider string         `json:"provider"`
	Kind     string         `json:"kind,omitempty"`
	Readings []string       `json:"readings,omitempty"`
	Actions  map[string]any `json:"actions,omitempty"`
	Hidden   bool           `json:"hidden,omitempty"`
}

func (d *Device) Supports(action string) bool {
	_, ok := d.Actions[action]
	return ok
}

type Session struct {
	ID        ID        `json:"id"`
	UserID    ID        `json:"user_id"`
	CreatedAt time.Time `json:"created_at"`
	ExpiresAt time.Time `json:"expires_at"`
	IP        string    `json:"ip,omitempty"`
	UserAgent string    `json:"user_agent,omitempty"`
}

func (s *Session) Expired(now time.Time) bool { return !now.Before(s.ExpiresAt) }

type Entry struct {
	ID       string         `json:"id"`
	At       time.Time      `json:"at"`
	Kind     string         `json:"kind"`
	Actor    Subject        `json:"actor"`
	IP       string         `json:"ip,omitempty"`
	UA       string         `json:"ua,omitempty"`
	Resource string         `json:"resource,omitempty"`
	Action   string         `json:"action,omitempty"`
	Result   string         `json:"result"`
	Detail   map[string]any `json:"detail,omitempty"`
	PrevHash string         `json:"prev_hash,omitempty"`
	Hash     string         `json:"hash,omitempty"`
}

type Query struct {
	Kind   string
	Result string
	From   time.Time
	To     time.Time
}

type Users interface {
	Get(ctx context.Context, id ID) (*User, error)
	GetByPhone(ctx context.Context, phone string) (*User, error)
	Create(ctx context.Context, u *User) error
	Update(ctx context.Context, u *User) error
	List(ctx context.Context) ([]*User, error)
}

type Policies interface {
	ListBySubject(ctx context.Context, kind SubjectKind, id ID) ([]Policy, error)
	ListAll(ctx context.Context) ([]Policy, error)
	Insert(ctx context.Context, p *Policy) error
	Delete(ctx context.Context, id ID) error
}

type Devices interface {
	Get(ctx context.Context, key string) (*Device, error)
	List(ctx context.Context) ([]*Device, error)
	Upsert(ctx context.Context, d *Device) error
	Delete(ctx context.Context, key string) error
}

type Sessions interface {
	Get(ctx context.Context, id ID) (*Session, error)
	Create(ctx context.Context, s *Session) error
	Delete(ctx context.Context, id ID) error
	List(ctx context.Context) ([]*Session, error)
}

type AuditStore interface {
	Append(ctx context.Context, e Entry) error
	Query(ctx context.Context, q Query, limit int) ([]Entry, error)
	LastHash(ctx context.Context) (string, error)
}

// Store is the single seam between business logic and persistence.
type Store interface {
	Users() Users
	Policies() Policies
	Devices() Devices
	Sessions() Sessions
	Audit() AuditStore

	// Tx runs fn inside one atomic boundary. The file implementation applies
	// the mutation to a copy and only commits when fn returns nil; a SQL
	// implementation maps it to BEGIN/COMMIT.
	Tx(ctx context.Context, fn func(Store) error) error

	Close() error
}
